-- 페이지 객체를 만든다

public record PageResult<T>(
        List<T> content, int page, int size,
        long totalElements, int totalPages, boolean hasNext) {
}


-- 리포지토리에 페이징을 넣는다

public PageResult<MemberTeamDto> searchPage(MemberSearchCondition cond,
                                            int page, int size) {
    List<MemberTeamDto> content = queryFactory
            .select(new QMemberTeamDto(
                    member.id, member.username, member.age,
                    team.id, team.name))
            .from(member)
            .leftJoin(member.team, team)
            .where(usernameEq(cond.getUsername()),
                   teamNameEq(cond.getTeamName()),
                   ageBetween(cond.getAgeGoe(), cond.getAgeLoe()))
            .orderBy(member.id.asc())
            .offset((long) page * size)
            .limit(size)
            .fetch();

    Long total = queryFactory
            .select(member.count())
            .from(member)
            .leftJoin(member.team, team)
            .where(usernameEq(cond.getUsername()),
                   teamNameEq(cond.getTeamName()),
                   ageBetween(cond.getAgeGoe(), cond.getAgeLoe()))
            .fetchOne();

    int totalPages = (int) Math.ceil((double) total / size);
    boolean hasNext = page + 1 < totalPages;

    return new PageResult<>(content, page, size, total, totalPages, hasNext);
}

